#!/usr/bin/env python3
"""Делает ordynka/index.html и manifest из Симонова. Запускать после patch_engine.py не нужно: скрипт самостоятельный.
Запуск из папки ordynka: python3 tools/patch_html.py"""
import re
from pathlib import Path
B = Path(__file__).resolve().parent.parent
R = B.parent

def sub(text, old, new):
    assert old in text, "не найдено: " + old[:70]
    return text.replace(old, new, 1)

h = (R / "index.html").read_text(encoding="utf-8")
h = re.sub(r'\s*<p class="more-tour">.*?</p>', "", h, flags=re.S)   # ссылка на Ордынку на экране Симонова здесь не нужна
h = sub(h, "<title>Симонов монастырь — историческая прогулка</title>", "<title>Скорбященский храм на Ордынке — аудиопрогулка</title>")
h = re.sub(r'<meta name="description" content="[^"]*" />', '<meta name="description" content="Аудиопрогулка у храма иконы «Всех скорбящих Радость» на Большой Ордынке: восемь остановок, старые фотографии, рассказы и пешеходная навигация." />', h, count=1)
h = sub(h, 'href="css/simonov-identity.css"', 'href="css/identity.css"')
old_css = B / "css" / "simonov-identity.css"
if old_css.exists():
    old_css.rename(B / "css" / "identity.css")
h = sub(h, "Историческая прогулка · Москва", "Аудиопрогулка · Москва")
h = sub(h, "Симонов<br>монастырь</h1>", "Скорбященский<br>храм</h1>")
h = sub(h, "Семь веков веры, крепости и памяти. Пройдите по местам, где история Москвы до сих пор видна в камне.",
        "Храм на Большой Ордынке: церковь стрелецкой слободы, колокольня Баженова, ротонда Бове и дом Ахматовой напротив. Восемь остановок.")
h = sub(h, "Москва, Восточная улица, 4", "Москва, Большая Ордынка, 20")
h = sub(h, 'aria-label="Ключевые даты истории Симонова монастыря"', 'aria-label="Ключевые даты истории храма на Ордынке"')
dates = [("1625", "первое упоминание церкви"), ("1783–1791", "трапезная и колокольня Баженова"), ("1836", "освящение ротонды Бове"),
         ("1930-е", "храм закрыт"), ("1948", "храм возвращён верующим")]
def group(hidden):
    items = "".join(f'<span><b>{d}</b> {t}</span><i aria-hidden="true">✦</i>' for d, t in dates)
    return f'<div class="date-marquee-group"{" aria-hidden=" + chr(34) + "true" + chr(34) if hidden else ""}>{items}</div>'
i0 = h.index('<div class="date-marquee-track">')
i1 = h.index('<section class="screen" id="screen-tour">')
h = h[:i0] + '<div class="date-marquee-track">' + group(False) + group(True) + '</div>\n        </div>\n      </div>\n    </section>\n\n    ' + h[i1:]
h = sub(h, "Восемь точек вокруг монастыря. Когда вы подойдёте примерно на 25 метров,", "Восемь точек у храма и рядом. Они стоят близко, в 20–35 метрах друг от друга. Когда вы подойдёте примерно на 20 метров,")
h = sub(h, '<p class="hint" id="offline-audio-status" aria-live="polite"></p>\n        </div>',
        '<p class="hint" id="offline-audio-status" aria-live="polite"></p>\n        </div>\n        <p class="hint hidden" id="offline-audio-none">Пока рассказы читает сам телефон («временный голос»). Тексты и фото сохраняются для работы без интернета при первом открытии.</p>')
h = sub(h, '<audio id="player" ', '<p class="hint tts-note hidden" id="tts-note" role="note"><b>Временный голос.</b> Рассказ читает озвучка вашего телефона, запись диктора появится позже. Нужен русский голос в настройках телефона.</p>\n          <audio id="player" ')
h = sub(h, 'aria-label="Кинохроника Симонова монастыря"', 'aria-label="Кинохроника"')
h = sub(h, "Это короткая аудиоэкскурсия по Симонову монастырю.", "Это короткая аудиоэкскурсия по храму «Всех скорбящих Радость» на Большой Ордынке.")
h = sub(h, "Восемь остановок вокруг стен и храма. На каждой звучит рассказ на три-четыре минуты, а текст можно читать с экрана.",
        "Восемь остановок у храма и рядом: ограда, ротонда, усадьба напротив, трапезная, колокольня, икона, XX век и дом Ахматовой. На каждой звучит рассказ на две-три минуты, а текст можно читать с экрана.")
h = sub(h, "Аудиорассказы загружаются с сервера и для прослушивания требуют интернет.",
        "Пока рассказ читает озвучка телефона («временный голос»): ей нужен русский голос в настройках. Когда появится запись диктора, её можно будет скачать для работы без интернета.")
h = sub(h, "Снимки взяты с Викисклада, где они помечены как свободные. Точки съёмки, где это было возможно, сверены с PastVu. Сами изображения с PastVu мы не берём: их правила разрешают только личное некоммерческое использование. Часть ракурсов приблизительная: городской GPS легко ошибается на несколько метров.",
        "Снимки взяты с Викисклада, где они помечены как свободные. Автор, год и лицензия каждого снимка указаны под фото. Точки съёмки старых кадров точно не известны, поэтому ракурс приблизительный. Городской GPS легко ошибается на несколько метров, а точки стоят близко друг к другу.")
new_tail = """<h3>Официальный храм</h3>
        <p>Храм иконы Божией Матери «Всех скорбящих Радость» на Большой Ордынке: <a href="https://ordynka.com/" target="_blank" rel="noopener">ordynka.com</a>. Расписание богослужений и экскурсий смотрите на сайте храма, оно может меняться.</p>
        <h3>Безопасность</h3>
        <p>Улицу переходите только по пешеходному переходу. Во дворы не заходите, если ворота закрыты. В храме ведите себя тихо: это действующая церковь.</p>
        <h3>Видео</h3>
        <p>Архивной кинохроники именно этого храма, которую можно законно показывать на сайте, мы не нашли. Подробности и платные варианты: файл <code>docs/VIDEO.md</code>.</p>
        <h3>Источники</h3>
        <ul><li><a href="https://ru.wikipedia.org/wiki/Храм_иконы_Божией_Матери_«Всех_скорбящих_Радость»_на_Большой_Ордынке" target="_blank" rel="noopener">Храм на Большой Ордынке — Википедия</a></li><li><a href="https://um.mos.ru/houses/tserkov_ikony_vsekh_skorbyashchikh_radost/" target="_blank" rel="noopener">«Узнай Москву»</a></li><li><a href="https://ordynka.com/o-hrame/" target="_blank" rel="noopener">О храме — сайт храма</a></li><li><a href="https://sobory.ru/article/?object=02244" target="_blank" rel="noopener">sobory.ru</a></li><li><a href="https://ru.wikipedia.org/wiki/Большая_Ордынка" target="_blank" rel="noopener">Большая Ордынка — Википедия</a></li></ul>
        <p>Полный список источников и прав на снимки лежит в файлах <code>SOURCES.md</code> и <code>RIGHTS.md</code> в папке этой экскурсии.</p>
        <p><a href="../">Ещё экскурсия: Симонов монастырь</a></p>
        <h3>Карта</h3>"""
j0 = h.index("<h3>Официальный храм</h3>")
j1 = h.index("<h3>Карта</h3>") + len("<h3>Карта</h3>")
h = h[:j0] + new_tail + h[j1:]
(B / "index.html").write_text(h, encoding="utf-8")

m = (R / "manifest.webmanifest").read_text(encoding="utf-8")
m = sub(m, "Симонов монастырь — аудиоэкскурсия", "Скорбященский храм на Ордынке — аудиоэкскурсия")
m = sub(m, '"short_name": "Симонов"', '"short_name": "Ордынка"')
(B / "manifest.webmanifest").write_text(m, encoding="utf-8")
print("html ok")
